function artifactSummary(item:any){const p=item.payload||{};if(item.kind==="research_plan")return p.intent?.intent_summary||"Research plan compiled.";if(item.kind==="discovery_result")return ((p.candidates||[]).length||0)+" dataset candidates discovered.";if(item.kind==="geo_sample_metadata")return Object.values(p.samples_by_candidate||{}).flat().length+" GEO samples expanded into sample-level metadata.";if(item.kind==="evidence_review")return (p.candidate_count??(p.candidates||[]).length??0)+" candidates reviewed against evidence.";if(item.kind==="preflight_report")return ((p.reports||[]).length||0)+" bundles assessed for readiness.";if(item.kind==="acquisition_plan")return ((p.recommended_bundle_ids||[]).length||0)+" bundles recommended for acquisition.";return p.summary||p.next_action||"Structured workflow output recorded."}
function taskArtifacts(task:WorkflowTask,artifacts:any[]){const ids=new Set(task.output_artifact_ids||[]);return artifacts.filter(item=>ids.has(item.artifact_id))}
const MODEL_STAGE_SUMMARY:Record<string,string>={
  intent_analysis:"Interpreted the scientific intent, hard constraints, desired outcome, and unresolved ambiguities.",
  study_design:"Turned the request into an evidence-aware study design, data requirements, and validation sequence.",
  critical_review:"Challenged assumptions, checked feasibility, and identified claims that require stronger evidence.",
  synthesis:"Reconciled the draft and critique into the final executable research plan.",
  query_planning:"Translated the research requirements into source-specific search queries.",
  requirement_compilation:"Converted the request into explicit machine-checkable requirements.",
  research_planning:"Prepared the research strategy and execution contracts.",
  pair_unit_resolution:"Evaluated whether modalities can be linked to the same biological unit.",
  pairing_verification:"Checked pairing claims against available repository and sample evidence."
};
function uniqueText(values:(string|null|undefined)[]){return Array.from(new Set(values.map(value=>value?.trim()).filter((value):value is string=>Boolean(value))))}
function compactValue(value:any){if(typeof value==="string")return value;if(value?.query)return value.query;if(value?.text)return value.text;if(value?.label)return value.label;if(value?.value)return String(value.value);return ""}
function callMatchesTask(call:any,task:WorkflowTask){if(call.created_at&&task.created_at&&task.updated_at){const callTime=Date.parse(call.created_at),started=Date.parse(task.created_at),finished=Date.parse(task.updated_at)+1000;if(Number.isFinite(callTime)&&Number.isFinite(started)&&Number.isFinite(finished)&&(callTime<started||callTime>finished))return false}const role=String(call.role||"").toLowerCase(),stage=String(call.stage||"").toLowerCase(),agent=task.agent.toLowerCase();if(agent==="research_planner")return ["planner","review","research"].some(value=>role.includes(value))||["intent_analysis","study_design","critical_review","synthesis","research_planning","requirement_compilation"].includes(stage);if(agent==="resource_discovery")return role.includes("discovery")||role.includes("query")||stage.includes("query");if(agent.includes("evidence"))return role.includes("evidence")||role.includes("curation")||stage.includes("pairing_verification");if(agent.includes("asset")||agent.includes("inventory"))return role.includes("asset")||role.includes("inventory")||stage.includes("pair_unit");if(agent.includes("acquisition"))return role.includes("acquisition");return role.includes(agent.replaceAll("_",""))}
function taskMessages(task:WorkflowTask,messages:any[]){const ids=new Set(task.output_artifact_ids||[]);return messages.filter(message=>(message.artifact_ids||[]).some((id:string)=>ids.has(id)))}
function reasoningBullets(task:WorkflowTask,items:any[],calls:any[],messages:any[]){const bullets:string[]=[];calls.forEach(call=>bullets.push(call.summary||call.purpose||MODEL_STAGE_SUMMARY[call.stage]||"Used "+titleCase(call.stage||"model-assisted analysis")+" to evaluate this stage."));for(const item of items){const p=item.payload||{};if(item.kind==="research_plan"){bullets.push(p.intent?.intent_summary,p.readiness_rationale);const gaps=(p.capability_gaps||[]).slice(0,1).map(compactValue);bullets.push(...gaps.map((gap:string)=>"Capability check: "+gap))}else if(item.kind==="query_plan"){const queries=(p.queries||[]).slice(0,2).map(compactValue).filter(Boolean);if(queries.length)bullets.push("Search focus: "+queries.join(" · "));if((p.uncovered_sources||[]).length)bullets.push("Coverage gap considered: "+words(p.uncovered_sources))}else if(item.kind==="evidence_review"&&p.next_action)bullets.push("Evidence review determined the next action: "+p.next_action);else if(item.kind==="preflight_report")bullets.push("Compared each bundle with readiness, access, license, and required-role checks.");else if(item.kind==="acquisition_plan")bullets.push("Ranked eligible bundles by evidence strength and acquisition readiness.");else if(item.kind.includes("inventory"))bullets.push("Resolved repository records into concrete files and semantic data bundles.");else if(item.kind==="lineage_report")bullets.push("Checked study-family relationships for possible evaluation leakage.")}
  messages.forEach(message=>{if(message.recommendation)bullets.push("Recommended next step: "+message.recommendation)});if(!calls.length)bullets.unshift(agentHelp(task.agent)+" No direct model call was recorded for this task.");return uniqueText(bullets).slice(0,4)}
function resultBullets(items:any[],messages:any[]){const bullets=items.map(artifactSummary);for(const item of items){const p=item.payload||{};for(const [label,value] of stageFacts(item)){if(!/^\d+(?:\.\d+)?$/.test(value)&&value!=="—")bullets.push(label+": "+value)}if(p.readiness_rationale)bullets.push(p.readiness_rationale)}messages.forEach(message=>{if(message.recommendation)bullets.push("Next: "+message.recommendation)});return uniqueText(bullets).slice(0,5)}
function metricValue(value:string){const parsed=Number(value);return Number.isFinite(parsed)?new Intl.NumberFormat("en",{notation:parsed>=10000?"compact":"standard",maximumFractionDigits:1}).format(parsed):value}
function taskMetrics(items:any[],calls:any[]){const metrics:{label:string;value:string}[]=[];for(const item of items){for(const [label,value] of stageFacts(item)){if(/^\d+(?:\.\d+)?$/.test(value)&&!metrics.some(metric=>metric.label===label))metrics.push({label,value:metricValue(value)})}}if(calls.length){const tokens=calls.reduce((sum,call)=>sum+Number(call.usage?.total_tokens||0),0),latency=calls.reduce((sum,call)=>sum+Number(call.latency_ms||0),0);metrics.push({label:"Model calls",value:String(calls.length)});if(tokens)metrics.push({label:"Tokens",value:metricValue(String(tokens))});if(latency)metrics.push({label:"Model time",value:(latency/1000).toFixed(latency>=10000?0:1)+"s"})}else if(items.length&&!metrics.length)metrics.push({label:"Artifacts",value:String(items.length)});return metrics.slice(0,4)}
function OutputPanel({tasks,artifacts,messages,llmCalls,selected,language,topology}:{tasks:WorkflowTask[];artifacts:any[];messages:any[];llmCalls:any[];selected:string|null;language:Language;topology:any}){const[expanded,setExpanded]=useState<Record<string,boolean>>({});return <section className="output-panel"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"阶段详情":"Live inspector"}</p><h2>{language==="zh"?"运行解读":"LIVE INSPECTOR"}</h2></div><span className="count-chip">{tasks.length}</span></div><div className="output-list">{tasks.map((task,index)=>{const items=taskArtifacts(task,artifacts),stageMessages=taskMessages(task,messages),calls=llmCalls.filter(call=>callMatchesTask(call,task)),reasoning=reasoningBullets(task,items,calls,stageMessages),results=resultBullets(items,stageMessages),metrics=taskMetrics(items,calls),open=expanded[task.task_id]??(task.status==="running"||task.task_id===selected);return <article className={"output-stage "+task.status} key={task.task_id}><button type="button" className="stage-toggle" aria-expanded={open} onClick={()=>setExpanded(current=>({...current,[task.task_id]:!open}))}><span className="stage-index">{String(index+1).padStart(2,"0")}</span><span className="stage-copy"><b>{workflowStageLabel(task,topology,language)}</b><small>{language==="zh"?items.length+" 项产出 · "+calls.length+" 次模型分析":items.length+" outputs · "+calls.length+" model calls"}</small></span><span className={"pill "+task.status}>{statusText(task.status,language)}</span><span className="stage-chevron">{open?"−":"+"}</span></button>{open?<div className="stage-body inspector-body">{metrics.length?<div className="inspector-stats" aria-label={language==="zh"?"阶段指标":"Stage statistics"}>{metrics.map(metric=><div className="inspector-stat" key={metric.label}><b>{metric.value}</b><span>{metricLabel(metric.label,language)}</span></div>)}</div>:null}<div className="inspector-summary-grid"><section className="inspector-summary reasoning-summary"><h3><span>01</span>{language==="zh"?"判断依据":"Thinking summary"}</h3>{reasoning.length?<ul>{reasoning.map((bullet,index)=><li key={index}>{localizedText(bullet,language)}</li>)}</ul>:<p className="muted-copy">{language==="zh"?"正在整理本阶段的判断依据。":"This stage is still preparing its analysis."}</p>}</section><section className="inspector-summary result-summary"><h3><span>02</span>{language==="zh"?"阶段结论":"Result"}</h3>{results.length?<ul>{results.map((bullet,index)=><li key={index}>{localizedText(bullet,language)}</li>)}</ul>:<p className="muted-copy">{task.status==="running"?(language==="zh"?"本阶段完成后显示结论。":"The result will appear when this stage completes."):(language==="zh"?"本阶段暂无可展示的结论。":"No structured output was recorded for this stage.")}</p>}</section></div>{items.length?<div className="artifact-tags" aria-label={language==="zh"?"阶段产出类型":"Produced artifact types"}>{items.map(item=><span key={item.artifact_id}>{artifactLabel(item.kind,language)}</span>)}</div>:null}</div>:null}</article>})}</div></section>}
function HumanLoopPanel({checkpoints,runId,onChanged,language}:{checkpoints:any[];runId:string;onChanged:()=>void;language:Language}){const[tab,setTab]=useState<"approval"|"message">("approval"),[message,setMessage]=useState(""),[reply,setReply]=useState(""),[error,setError]=useState("");const open=checkpoints.filter(item=>item.status==="open");const resolve=async(checkpoint:any,option:any)=>{setError("");const response=await fetch("/checkpoints/"+checkpoint.checkpoint_id+"/resolve",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({resolution:{option:option.id}})});if(!response.ok){setError(ui(language,"decisionError"));return}await onChanged();setReply(ui(language,"decisionSubmitted"))};const ask=async(event:any)=>{event.preventDefault();if(!message.trim())return;setError("");const response=await fetch("/runs/"+runId+"/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message})});if(!response.ok){setError(ui(language,"messageError"));return}const artifact=await response.json();setReply(artifact.payload?.assistant||(language==="zh"?"已记录你的补充指令。":"Your intervention was recorded."));setMessage("");await onChanged()};return <section className="human-loop"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"流程控制":"Human in the loop"}</p><h2>{ui(language,"humanLoop")}</h2></div><span className={open.length?"approval-dot":"idle-dot"}/></div><div className="loop-tabs" role="tablist"><button role="tab" aria-selected={tab==="approval"} className={tab==="approval"?"active":""} onClick={()=>setTab("approval")}>{ui(language,"approval")} {open.length?<span>{open.length}</span>:null}</button><button role="tab" aria-selected={tab==="message"} className={tab==="message"?"active":""} onClick={()=>setTab("message")}>{ui(language,"askAgent")}</button></div>{tab==="approval"?<div className="tab-content">{open.length?open.map(checkpoint=><div className="decision" key={checkpoint.checkpoint_id}><strong>{localizedText(checkpoint.title,language)}</strong><p>{checkpoint.recommendation?localizedText(checkpoint.recommendation,language):(language==="zh"?"请确认是否按建议继续执行。":"Review the proposed action before the workflow continues.")}</p><div className="decision-options">{checkpoint.options.map((option:any)=><button className={option.id==="plan_only"?"secondary":"primary"} key={option.id} onClick={()=>resolve(checkpoint,option)}>{localizedText(option.label,language)}</button>)}</div></div>):<div className="autonomous-state"><b>{ui(language,"noApproval")}</b><p>{ui(language,"autonomous")}</p></div>}</div>:<form className="intervention-form" onSubmit={ask}><label htmlFor="agent-message">{ui(language,"sendInstruction")}</label><textarea id="agent-message" value={message} onChange={event=>setMessage(event.target.value)} rows={3} placeholder={ui(language,"instructionPlaceholder")}/><button className="primary">{ui(language,"send")}</button></form>}{reply?<p className="loop-reply">{localizedText(reply,language)}</p>:null}{error?<p className="loop-error">{error}</p>:null}</section>}
type CatalogSheetId="studies"|"pair_units"|"files"|"audit_hold";
type CatalogColumn={key:string;en:string;zh:string;group?:"identity"|"queue"|"audit"|"metadata";link?:boolean;numeric?:boolean;code?:boolean};
const CATALOG_SHEETS:{id:CatalogSheetId;code:string;en:string;zh:string;descriptionEn:string;descriptionZh:string;columns:CatalogColumn[]}[]=[
  {id:"studies",code:"01",en:"Studies",zh:"研究",descriptionEn:"Study-level evidence, catalog state, and next action.",descriptionZh:"研究级证据、目录状态与后续动作。",columns:[
    {key:"study_accession",en:"Study accession",zh:"研究编号",code:true},{key:"study_title",en:"Study title",zh:"研究标题"},{key:"repository",en:"Repository",zh:"数据库"},{key:"public_year",en:"Public year",zh:"公开年份",numeric:true},{key:"method",en:"Method",zh:"实验方法"},{key:"human_material",en:"Human material",zh:"人源材料"},{key:"assembly",en:"Assembly",zh:"参考基因组",code:true},{key:"catalog_status",en:"Catalog status",zh:"目录状态",code:true},{key:"catalog_status_detail",en:"Status detail",zh:"状态说明"},{key:"priority",en:"Priority",zh:"优先级",code:true},{key:"next_action",en:"Next action",zh:"后续动作"},{key:"same_cell_evidence",en:"Same-cell evidence",zh:"同细胞证据"},{key:"fragment_evidence",en:"Fragment evidence",zh:"ATAC fragment 证据"},{key:"rna_count_evidence",en:"RNA count evidence",zh:"RNA count 证据"},{key:"metadata_evidence",en:"Metadata evidence",zh:"元数据证据"},{key:"source_url",en:"Source",zh:"来源链接",link:true}
  ]},
  {id:"pair_units",code:"02",en:"Pair units",zh:"配对单元",descriptionEn:"Traceable same-cell RNA–ATAC logical units.",descriptionZh:"可追溯的同细胞 RNA–ATAC 逻辑配对单元。",columns:[
    {key:"study_accession",en:"Study accession",zh:"研究编号",code:true},{key:"pair_unit_id",en:"Pair unit ID",zh:"配对单元 ID",code:true},{key:"sample_condition",en:"Sample / condition",zh:"样本 / 条件"},{key:"atac_gsm",en:"ATAC GSM",zh:"ATAC GSM",code:true},{key:"rna_gsm",en:"RNA GSM",zh:"RNA GSM",code:true},{key:"assembly",en:"Assembly",zh:"参考基因组",code:true},{key:"pairing_key",en:"RNA–ATAC pairing key",zh:"RNA–ATAC 配对键"},{key:"pairing_evidence",en:"Pairing evidence",zh:"配对证据"},{key:"rna_count_scope",en:"RNA count scope",zh:"RNA count 范围"},{key:"metadata_status",en:"Metadata status",zh:"元数据状态"},{key:"manifest_status",en:"Manifest status",zh:"文件清单状态",code:true},{key:"priority",en:"Priority",zh:"优先级",code:true},{key:"notes",en:"Notes",zh:"关键说明"},{key:"source_url",en:"Source",zh:"来源链接",link:true}
  ]},
  {id:"files",code:"03",en:"Files",zh:"文件清单",descriptionEn:"Exact files, URLs, sizes, roles, and post-download checks.",descriptionZh:"逐文件记录下载地址、大小、文件角色与下载后检查。",columns:[
    {key:"dataset_id",en:"Dataset ID",zh:"数据集 ID",code:true},{key:"pair_unit_id",en:"Pair unit ID",zh:"配对单元 ID",code:true},{key:"file_accession",en:"File accession",zh:"文件 accession",code:true},{key:"assembly",en:"Assembly",zh:"参考基因组",code:true},{key:"omics_layer",en:"Omics layer",zh:"组学层级"},{key:"file_role",en:"File role",zh:"文件角色",code:true},{key:"filename",en:"Filename",zh:"文件名",code:true},{key:"size_bytes",en:"Size",zh:"文件大小",numeric:true},{key:"url_status",en:"URL status",zh:"链接状态",code:true},{key:"audit_status",en:"Audit status",zh:"审计状态",code:true},{key:"priority",en:"Priority",zh:"优先级",code:true},{key:"expected_downstream_action",en:"Post-download action",zh:"下载后动作"},{key:"download_url",en:"Download URL",zh:"下载链接",link:true}
  ]},
  {id:"audit_hold",code:"04",en:"Audit / hold",zh:"审计 / 暂缓",descriptionEn:"Blocking reasons, audit procedure, pass criteria, and release conditions.",descriptionZh:"阻断原因、审计步骤、通过标准与解除条件。",columns:[
    {key:"priority",en:"Priority",zh:"优先级",group:"identity",code:true},{key:"record_level",en:"Record level",zh:"记录层级",group:"identity"},{key:"study_accession",en:"Study accession",zh:"研究编号",group:"identity",code:true},{key:"pair_unit_or_sample_scope",en:"Pair unit / scope",zh:"配对单元 / 样本范围",group:"identity"},{key:"queue_action",en:"Queue action",zh:"队列动作",group:"queue",code:true},{key:"blocking_category",en:"Blocking category",zh:"阻断类别",group:"queue",code:true},{key:"category_family",en:"Category family",zh:"问题类别",group:"queue"},{key:"blocking_reason_detail",en:"Why not archived",zh:"未归档原因",group:"audit"},{key:"audit_method",en:"Audit method",zh:"审计方法",group:"audit"},{key:"audit_steps",en:"Audit steps",zh:"审计步骤",group:"audit"},{key:"pass_criteria",en:"Pass criteria",zh:"通过标准",group:"audit"},{key:"failure_handling",en:"If validation fails",zh:"未通过处理",group:"audit"},{key:"next_action",en:"Expected output / action",zh:"预期动作",group:"audit"},{key:"source_url",en:"Source",zh:"来源链接",group:"metadata",link:true},{key:"audit_date",en:"Audit date",zh:"审计日期",group:"metadata"},{key:"raw_status_code",en:"Raw status code",zh:"原始状态代码",group:"metadata",code:true}
  ]}
];
function catalogValue(row:any,column:CatalogColumn,language:Language){const value=row?.[column.key];if(value===null||value===undefined||value==="")return "—";if(column.key==="size_bytes"&&Number.isFinite(Number(value))){const bytes=Number(value),units=["B","KB","MB","GB","TB"];let size=bytes,index=0;while(size>=1024&&index<units.length-1){size/=1024;index++}return size.toFixed(index>1?2:0)+" "+units[index]}if(Array.isArray(value))return value.join(language==="zh"?"、":", ");if(typeof value==="object")return JSON.stringify(value);return localizedValue(value,language)}
function CatalogWorkspace({catalog,runId,language}:{catalog:any|undefined|null;runId:string;language:Language}){const[active,setActive]=useState<CatalogSheetId>("studies"),[query,setQuery]=useState(""),[page,setPage]=useState(0);const sheet=CATALOG_SHEETS.find(item=>item.id===active)!,rows:any[]=catalog?.[active]||[],needle=query.trim().toLocaleLowerCase(),filtered=needle?rows.filter(row=>Object.values(row).some(value=>String(value??"").toLocaleLowerCase().includes(needle))):rows,pageSize=20,pageCount=Math.max(1,Math.ceil(filtered.length/pageSize)),safePage=Math.min(page,pageCount-1),visible=filtered.slice(safePage*pageSize,(safePage+1)*pageSize);const choose=(id:CatalogSheetId)=>{setActive(id);setQuery("");setPage(0)};return <div className="catalog-workspace"><div className="catalog-tabs" role="tablist" aria-label={language==="zh"?"候选数据子表":"Candidate dataset sheets"}>{CATALOG_SHEETS.map(item=><button type="button" role="tab" aria-selected={active===item.id} className={active===item.id?"active":""} key={item.id} onClick={()=>choose(item.id)}><b>{item.code}</b><span>{language==="zh"?item.zh:item.en}</span><em>{catalog?.[item.id]?.length||0}</em></button>)}</div><div className="catalog-toolbar"><div><strong>{sheet.code}_{language==="zh"?sheet.zh:sheet.en}</strong><p>{language==="zh"?sheet.descriptionZh:sheet.descriptionEn}</p></div><div className="catalog-actions"><label><span className="sr-only">{language==="zh"?"搜索当前子表":"Search current sheet"}</span><input type="search" value={query} onChange={event=>{setQuery(event.target.value);setPage(0)}} placeholder={language==="zh"?"搜索当前子表…":"Search this sheet…"}/></label><a className="catalog-download" href={"/runs/"+runId+"/curation-catalog.xlsx"}>{language==="zh"?"下载 Excel":"Download XLSX"}</a></div></div>{catalog===undefined?<div className="catalog-message"><span className="catalog-loader"/>{language==="zh"?"正在整理四张子表…":"Preparing the four catalog sheets…"}</div>:catalog===null?<div className="catalog-message error">{language==="zh"?"暂时无法读取四张子表，请稍后刷新。":"The catalog sheets are temporarily unavailable. Please refresh shortly."}</div>:<><div className={"catalog-table-wrap sheet-"+active}><table className="catalog-table"><thead><tr>{sheet.columns.map(column=><th className={"group-"+(column.group||"identity")} key={column.key}>{language==="zh"?column.zh:column.en}</th>)}</tr></thead><tbody>{visible.length?visible.map((row,rowIndex)=><tr key={(row.study_accession||row.dataset_id||row.pair_unit_id||"row")+"-"+(safePage*pageSize+rowIndex)}>{sheet.columns.map(column=>{const value=catalogValue(row,column,language),status=/status|priority|queue_action/.test(column.key);return <td className={(column.code?" code-cell":"")+(column.numeric?" numeric-cell":"")+(status?" status-cell":"")} key={column.key} title={value}>{column.link&&value!=="—"?<a href={String(row[column.key])} target="_blank" rel="noreferrer">{language==="zh"?"打开链接 ↗":"Open ↗"}</a>:status&&value!=="—"?<span className={"catalog-status "+String(value).toLowerCase().replaceAll(/[^a-z0-9]+/g,"-")}>{value}</span>:value}</td>})}</tr>):<tr><td colSpan={sheet.columns.length}><div className="catalog-empty"><b>{language==="zh"?"当前子表暂无记录":"No records in this sheet yet"}</b><span>{language==="zh"?(active==="pair_units"?"流程尚未解析出可追溯的 RNA–ATAC 配对单元。":active==="files"?"流程尚未生成逐文件下载清单。":"没有符合当前筛选条件的记录。"):(active==="pair_units"?"No traceable RNA–ATAC pair units have been resolved yet.":active==="files"?"No file-level download manifest has been produced yet.":"No rows match the current filter.")}</span></div></td></tr>}</tbody></table></div><div className="catalog-footer"><span>{filtered.length?language==="zh"?"显示 "+(safePage*pageSize+1)+"–"+Math.min((safePage+1)*pageSize,filtered.length)+"，共 "+filtered.length+" 条":"Showing "+(safePage*pageSize+1)+"–"+Math.min((safePage+1)*pageSize,filtered.length)+" of "+filtered.length:language==="zh"?"0 条记录":"0 records"}</span><div><button type="button" disabled={safePage===0} onClick={()=>setPage(value=>Math.max(0,value-1))}>{language==="zh"?"上一页":"Previous"}</button><b>{safePage+1} / {pageCount}</b><button type="button" disabled={safePage>=pageCount-1} onClick={()=>setPage(value=>Math.min(pageCount-1,value+1))}>{language==="zh"?"下一页":"Next"}</button></div></div></>}</div>}
function ResultsPanel({artifacts,runId,language}:{artifacts:any[];runId:string;language:Language}){const[catalog,setCatalog]=useState<any|undefined|null>(undefined);const latest=(kind:string)=>artifacts.filter(item=>item.kind===kind).at(-1)?.payload||{};const discovery=latest("discovery_result"),evidence=latest("evidence_review"),preflight=latest("preflight_report"),acquisition=latest("acquisition_plan");const candidates=evidence.candidates||discovery.candidates||[],reports=preflight.reports||[],ready=reports.filter((item:any)=>item.decision==="preflight_ready").length,stats=[[ui(language,"candidates"),catalog?.studies?.length??evidence.candidate_count??candidates.length],[ui(language,"readyBundles"),ready],[ui(language,"recommended"),(acquisition.recommended_bundle_ids||[]).length]];useEffect(()=>{let alive=true;fetch("/runs/"+runId+"/curation-catalog").then(response=>response.ok?response.json():Promise.reject()).then(value=>{if(alive)setCatalog(value)}).catch(()=>{if(alive)setCatalog(null)});return()=>{alive=false}},[runId,artifacts.length]);return <section className="results-panel results-wide"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"筛选结果":"Downstream result"}</p><h2>{ui(language,"downstreamResult")}</h2></div><Help text={language==="zh"?"四张子表分别记录研究、配对单元、文件清单和待审计问题；所有值均来自本次运行产物。":"The four sheets contain studies, pair units, file manifests, and audit/hold items; every value comes from this run's artifacts."}/></div><div className="results-layout catalog-results-layout"><aside className="result-stats vertical">{stats.map(([label,value])=><div className="result-stat" key={String(label)}><b>{value as any}</b><span>{label}</span></div>)}</aside><CatalogWorkspace catalog={catalog} runId={runId} language={language}/></div></section>}
function modelUsageTotals(calls:any[]){return calls.reduce((totals,call)=>{const usage=call.usage||call.usage_metadata||{},prompt=Number(usage.prompt_tokens||usage.input_tokens||0),completion=Number(usage.completion_tokens||usage.output_tokens||0),total=Number(usage.total_tokens||usage.total_token_count||prompt+completion||0);return{prompt:totals.prompt+prompt,completion:totals.completion+completion,total:totals.total+total}},{prompt:0,completion:0,total:0})}
function modelProviderLabel(value:any){const key=String(value||"unknown").toLowerCase();return key==="stepfun"?"StepFun":key==="openai"?"OpenAI":key==="anthropic"?"Anthropic":key==="langchain"?"LangChain":String(value||"Unknown")}
function ModelUsageCard({calls,language}:{calls:any[];language:Language}){const usage=modelUsageTotals(calls),format=(value:number)=>new Intl.NumberFormat(language==="zh"?"zh-CN":"en-US").format(value),modelNames=Array.from(new Set(calls.map((call:any)=>modelProviderLabel(call.client||call.provider)+" API · "+String(call.model||"—")))),detail=language==="zh"?"Token 由模型供应商返回的输入与输出用量相加；当前显示已记录调用。":"Tokens are provider-reported input plus output usage for recorded calls.";return <div className="run-usage" title={detail}><span className="run-label">{language==="zh"?"MODEL API · 已记录":"MODEL API · RECORDED"}</span><div className="run-model-line"><small>{language==="zh"?"供应商与模型":"Provider & model"}</small><b>{modelNames.length?modelNames.join(" / "):"—"}</b></div><div className="run-usage-grid"><span><b>{format(calls.length)}</b><small>{language==="zh"?"调用次数":"API calls"}</small></span><span><b>{format(usage.total)}</b><small>{language==="zh"?"Token 总量":"Total tokens"}</small></span></div><p className="run-token-formula"><span>{language==="zh"?"输入":"Input"} {format(usage.prompt)}</span><i>+</i><span>{language==="zh"?"输出":"Output"} {format(usage.completion)}</span><i>=</i><strong>{format(usage.total)}</strong></p></div>}
function Run(){const{runId}=useParams();const[d,setD]=useState<any>();const[selected,setSelected]=useState<string|null>(null),[language,setLanguage]=useState<Language>(()=>localStorage.getItem("scdata-agent-language")==="zh"?"zh":"en");const load=()=>fetch("/runs/"+runId).then(x=>x.json()).then(setD);useEffect(()=>{load();const timer=window.setInterval(load,2500);const stream=new EventSource("/runs/"+runId+"/events");["task_started","task_finished","checkpoint_resolved","checkpoint_created"].forEach(type=>stream.addEventListener(type,load));return()=>{window.clearInterval(timer);stream.close()}},[runId]);useEffect(()=>{localStorage.setItem("scdata-agent-language",language);document.documentElement.lang=language==="zh"?"zh-CN":"en"},[language]);if(!d)return <Shell language={language} onLanguageChange={()=>setLanguage(current=>current==="en"?"zh":"en")}><p>{language==="zh"?"加载中…":"Loading…"}</p></Shell>;return <Shell language={language} onLanguageChange={()=>setLanguage(current=>current==="en"?"zh":"en")}><section className="run-page"><Link className="back-link" to="/#workspace">← {ui(language,"allRuns")}</Link><div className="run-hero"><div><span className={"pill "+d.run.status}>{statusText(d.run.status,language)}</span><h1>{d.run.question}</h1></div><div className="run-summary-cards"><div className="run-meta"><span className="run-label">{ui(language,"run")}</span><code>{d.run.run_id}</code><span className="stage-progress"><i/>{d.tasks.filter((task:any)=>task.status==="completed").length}/{d.tasks.length} {ui(language,"stagesComplete")}</span></div><ModelUsageCard calls={d.llm_calls||[]} language={language}/></div></div><div className="console-grid"><section className="left-console"><div className="card topology-card"><div className="section-heading"><div><p className="eyebrow">{language==="zh"?"流程图":"Process map"}</p><h2>{ui(language,"processMap")}</h2></div></div><WorkflowGraph tasks={d.tasks} topology={d.workflow_topology} selected={selected} language={language} runStatus={d.run.status} onSelect={task=>setSelected(current=>current===task.task_id?null:task.task_id)}/>{d.workflow_topology?.trace_complete===false?<p className="topology-trace-note">{ui(language,"partialTrace")}</p>:null}</div></section><aside className="right-console"><OutputPanel tasks={d.tasks} artifacts={d.artifacts} messages={d.messages||[]} llmCalls={d.llm_calls||[]} selected={selected} language={language} topology={d.workflow_topology}/></aside></div><HumanLoopPanel checkpoints={d.checkpoints} runId={d.run.run_id} onChanged={load} language={language}/><ResultsPanel artifacts={d.artifacts} runId={d.run.run_id} language={language}/></section></Shell>}
export function App(){return <Routes><Route path="/" element={<Home/>}/><Route path="/ui/runs/:runId" element={<Run/>}/><Route path="*" element={<Home/>}/></Routes>}
